<script setup>
import { ref, onMounted, computed } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useQuasar } from 'quasar'
import { useAuth } from '../stores/auth'
import { api, unwrap, errorMessage, downloadFile } from '../services/api'
import { statuses, accesses, accessOptions, canEdit, canSubmit, formatDate, safeUrl } from '../domain'
import PageHeading from '../components/PageHeading.vue'
import AsyncState from '../components/AsyncState.vue'
const route=useRoute(), router=useRouter(), auth=useAuth(), $q=useQuasar(), resource=ref(null), loading=ref(true), error=ref(''), busy=ref(false)
const review=ref(false), decision=ref('aprobado'), observations=ref(''), publish=ref(false), access=ref('publico')
const editable=computed(()=>resource.value&&canEdit(auth.user,resource.value))
async function load() { loading.value=true; error.value=''; try { resource.value=unwrap((await api.get(`/resources/${route.params.id}`)).data) } catch(e) { error.value=errorMessage(e) } finally { loading.value=false } }
async function action(name,body={}) { busy.value=true; try { resource.value=unwrap((await api.post(`/resources/${resource.value.id}/${name}`,body)).data); review.value=false; publish.value=false; $q.notify({type:'positive',message:'Operación registrada correctamente.'}) } catch(e) { $q.notify({type:'negative',message:errorMessage(e)}) } finally { busy.value=false } }
function submit() { $q.dialog({title:'Enviar a revisión',message:'El depósito dejará de ser editable hasta la decisión del revisor. ¿Desea enviarlo?',cancel:true,persistent:true}).onOk(()=>action('submit')) }
function withdraw() { $q.dialog({title:'Retirar publicación',message:'Indique el motivo del retiro. Se conservará la trazabilidad.',prompt:{model:'',type:'textarea',isValid:v=>v.trim().length>0&&v.length<=1000},cancel:true,persistent:true}).onOk(reason=>action('withdraw',{reason})) }
function remove() { $q.dialog({title:'Eliminar recurso',message:'Esta acción eliminará el registro. ¿Desea continuar?',cancel:true,ok:{label:'Eliminar',color:'negative'},persistent:true}).onOk(async()=>{busy.value=true;try { await api.delete(`/resources/${resource.value.id}`); $q.notify({type:'positive',message:'Recurso eliminado.'}); router.push('/depositos') } catch(e){$q.notify({type:'negative',message:errorMessage(e)})}finally{busy.value=false}}) }
async function download(file) { busy.value=true; try { await downloadFile(resource.value.id,file) } catch(e) { $q.notify({type:'negative',message:errorMessage(e)}) } finally { busy.value=false } }
async function cite() { const r=resource.value; const citation=`${r.authors?.map(a=>a.name).join(', ') || 'Universidad Luterana Salvadoreña'}. (${r.resource_date?.slice(0,4) || 's. f.'}). ${r.title}. SRICU-ULS. ${location.href}`; try { await navigator.clipboard.writeText(citation); $q.notify({type:'positive',message:'Referencia copiada.'}) } catch { $q.dialog({title:'Referencia bibliográfica',message:citation}) } }
onMounted(load)
</script>
<template><AsyncState :loading="loading" :error="error" @retry="load"><template v-if="resource"><PageHeading :title="resource.title" :subtitle="`${resource.type==='proyecto'?'Proyecto de software':'Documento académico'} · ${formatDate(resource.resource_date)}`" /><div class="details-layout"><div><section class="surface q-mb-lg"><div class="q-mb-lg"><span :class="['tag',`status-${resource.status}`]">{{ statuses[resource.status] }}</span> <span class="tag q-ml-sm">{{ accesses[resource.access_level] }}</span></div><h2>Resumen</h2><p class="resource-summary">{{ resource.description }}</p><dl class="metadata"><dt>Autoría</dt><dd>{{ resource.authors?.map(a=>a.name).join(', ') }}</dd><dt>Colección</dt><dd><router-link v-if="resource.collection" :to="`/colecciones/${resource.collection.id}`">{{ resource.collection.name }}</router-link><span v-else>Sin colección</span></dd><dt>Categoría</dt><dd>{{ resource.category?.name }}</dd><dt>Idioma</dt><dd>{{ resource.language }}</dd><dt>Palabras clave</dt><dd>{{ resource.keywords?.map(k=>k.name).join(', ') || 'Sin palabras clave' }}</dd><dt>Procedencia</dt><dd>{{ resource.provenance || 'No indicada' }}</dd><dt>Licencia</dt><dd>{{ resource.license?.name }}</dd></dl><template v-if="resource.type==='proyecto'"><h2 class="q-mt-xl">Información técnica</h2><p class="resource-summary">{{ resource.technical_description }}</p><p><strong>Tecnologías:</strong> {{ resource.technologies || 'No indicadas' }}</p><a v-if="safeUrl(resource.external_url)" :href="safeUrl(resource.external_url)" target="_blank" rel="noopener noreferrer">Abrir repositorio o enlace externo <q-icon name="open_in_new" /></a></template></section>
<section class="surface q-mb-lg"><h2>Archivos del recurso</h2><p v-if="!resource.files?.length" class="muted">Este recurso no tiene archivos adjuntos.</p><div v-for="file in resource.files" :key="file.id" class="file-row"><div><q-icon name="description" color="secondary" class="q-mr-sm" />{{ file.original_name || file.name || `Archivo ${file.id}` }}<small v-if="file.size" class="q-ml-sm">{{ (file.size/1024/1024).toFixed(2) }} MB</small></div><q-btn outline color="primary" icon="download" label="Descargar" :disable="!resource.download_allowed" :loading="busy" @click="download(file)" /></div><p v-if="!resource.download_allowed" class="notice">La licencia o su nivel de acceso no permiten descargar estos archivos.</p></section>
<section v-if="resource.reviews?.length" class="surface"><h2>Historial de revisión</h2><article v-for="item in resource.reviews" :key="item.id" class="q-mb-lg"><strong>{{ item.decision }} · {{ item.reviewer?.name }}</strong><p class="muted">{{ formatDate(item.created_at) }}</p><p>{{ item.observations || 'Sin observaciones.' }}</p></article></section><p v-if="resource.withdrawal_reason" class="notice">Motivo del retiro: {{ resource.withdrawal_reason }}</p></div>
<aside class="surface" style="align-self:start"><h2>Acciones</h2><q-btn outline color="primary" label="Copiar referencia" icon="content_copy" class="full-width q-mb-md" @click="cite" /><q-btn v-if="editable" outline color="primary" label="Editar metadatos y archivos" :to="`/depositos/${resource.id}/editar`" class="full-width q-mb-md" /><q-btn v-if="canSubmit(auth.user,resource)" unelevated color="primary" label="Enviar a revisión" class="full-width q-mb-md" :loading="busy" @click="submit" /><q-btn v-if="auth.canReview&&resource.status==='revision'" unelevated color="primary" label="Revisar depósito" class="full-width q-mb-md" @click="review=true" /><q-btn v-if="auth.canManage&&resource.status==='aprobado'" unelevated color="positive" label="Publicar recurso" class="full-width q-mb-md" @click="publish=true" /><q-btn v-if="auth.canManage&&resource.status==='publicado'" outline color="negative" label="Retirar publicación" class="full-width q-mb-md" :loading="busy" @click="withdraw" /><q-btn v-if="auth.isAdmin||(auth.user?.id===resource.owner_id&&resource.status==='borrador')" flat color="negative" label="Eliminar recurso" class="full-width" :loading="busy" @click="remove" /><p class="muted q-mt-lg q-mb-none">La disponibilidad de los archivos depende de la licencia y los permisos del recurso.</p></aside></div></template></AsyncState>
<q-dialog v-model="review" persistent><q-card class="dialog-card"><q-card-section><h2>Revisión y decisión</h2><p>Verifique metadatos, archivos y condiciones de uso antes de registrar una decisión.</p><q-form @submit="action('review',{decision,observations})"><q-select v-model="decision" :options="[{label:'Aprobar',value:'aprobado'},{label:'Devolver con observaciones',value:'devuelto'}]" emit-value map-options outlined label="Decisión" class="q-mb-lg" /><q-input v-model="observations" type="textarea" outlined label="Observaciones" :rules="[v=>decision!=='devuelto'||!!v.trim()||'Indique las correcciones necesarias']" /><div class="actions"><q-btn color="primary" type="submit" label="Registrar decisión" :loading="busy" /><q-btn flat label="Cancelar" :disable="busy" v-close-popup /></div></q-form></q-card-section></q-card></q-dialog>
<q-dialog v-model="publish" persistent><q-card class="dialog-card"><q-card-section><h2>Publicar recurso aprobado</h2><p>Confirme que la licencia y los derechos de distribución permiten esta publicación.</p><q-select v-model="access" :options="accessOptions" emit-value map-options outlined label="Nivel de acceso" /><div class="actions"><q-btn color="positive" label="Confirmar publicación" :loading="busy" @click="action('publish',{access_level:access})" /><q-btn flat label="Cancelar" :disable="busy" v-close-popup /></div></q-card-section></q-card></q-dialog>
</template>
